)) x where x->>'id'=o.invoice_id;\n   if i is null then raise exception 'Linked invoice must be retained with its order history';end if;\n   if i->>'quoteId' is distinct from o.quote_id or i->'items' is distinct from o.snapshot->'items' or i->'amount' is distinct from o.snapshot->'amount' or i->>'currency' is distinct from o.snapshot->>'currency' or i->>'client' is distinct from o.snapshot->>'client' or i->>'description' is distinct from o.snapshot->>'description' or i->>'serviceDetails' is distinct from o.snapshot->>'serviceDetails' or i->>'paymentDetails' is distinct from o.snapshot->>'paymentDetails' or i->>'deal' is distinct from o.snapshot->>'deal' or i->>'project' is distinct from o.snapshot->>'project' or i->>'orderReference' is distinct from o.order_data->>'number' or i->>'clientPoNumber' is distinct from (case when o.mode='client_lpo' then o.order_data->>'number' else o.po_approval->>'clientPoNumber' end) then raise exception 'Invoice scope and order references must match the accepted quotation';end if;\n  end if;\n end loop;\n for q in select x from jsonb_array_elements(coalesce(new.data->'quotes','[]')) x where x ? 'staffAcceptance' loop\n  if not exists(select 1 from quote_orders where organization_id=new.organization_id and quote_id=q->>'id' and acceptance=q->'staffAcceptance') then raise exception 'Acceptance is server controlled';end if;\n end loop;\n for i in select x from jsonb_array_elements(coalesce(new.data->'invoices','[]')) x where x ? 'quoteId' loop\n  if not exists(select 1 from quote_orders where organization_id=new.organization_id and quote_id=i->>'quoteId' and invoice_id=i->>'id') then raise exception 'Use Prepare invoice to link a quotation';end if;\n end loop;\n return new;\nend ", "new": "\ndeclare o quote_orders;q jsonb;i jsonb;\nbegin\n for o in select * from quote_orders where organization_id=new.organization_id loop\n  select x into q from jsonb_array_elements(coalesce(new.data->'quotes','[]')) x where x->>'id'=o.quote_id;\n  if q is null or q->>'status' is distinct from 'Accepted' or quote_order_content(q) is distinct from quote_order_content(o.snapshot) then raise exception 'Accepted quotation is locked. Create a new revision';end if;\n  if o.invoice_id is not null then\n   select x into i from jsonb_array_elements(coalesce(new.data->'invoices','[]')) x where x->>'id'=o.invoice_id;\n   if i is null then raise exception 'Linked invoice must be retained with its order history';end if;\n   if not exists(select 1 from public.staff_document_edit_versions e where e.organization_id=new.organization_id and e.document_id=i->>'id' and e.document_type='invoice' and e.new_record=i) and (i->>'quoteId' is distinct from o.quote_id or i->'items' is distinct from o.snapshot->'items' or i->'amount' is distinct from o.snapshot->'amount' or i->>'currency' is distinct from o.snapshot->>'currency' or i->>'client' is distinct from o.snapshot->>'client' or i->>'description' is distinct from o.snapshot->>'description' or i->>'serviceDetails' is distinct from o.snapshot->>'serviceDetails' or i->>'paymentDetails' is distinct from o.snapshot->>'paymentDetails' or i->>'deal' is distinct from o.snapshot->>'deal' or i->>'project' is distinct from o.snapshot->>'project' or i->>'orderReference' is distinct from o.order_data->>'number' or i->>'clientPoNumber' is distinct from (case when o.mode='client_lpo' then o.order_data->>'number' else o.po_approval->>'clientPoNumber' end) ) then raise exception 'Use Edit to save a tracked invoice amendment';end if;\n  end if;\n end loop;\n for q in select x from jsonb_array_elements(coalesce(new.data->'quotes','[]')) x where x ? 'staffAcceptance' loop\n  if not exists(select 1 from quote_orders where organization_id=new.organization_id and quote_id=q->>'id' and acceptance=q->'staffAcceptance') then raise exception 'Acceptance is server controlled';end if;\n end loop;\n for i in select x from jsonb_array_elements(coalesce(new.data->'invoices','[]')) x where x ? 'quoteId' loop\n  if not exists(select 1 from quote_orders where organization_id=new.organization_id and quote_id=i->>'quoteId' and invoice_id=i->>'id') then raise exception 'Use Prepare invoice to link a quotation';end if;\n end loop;\n return new;\nend "}]$entries$::jsonb) LOOP
 SELECT prosrc,pg_get_functiondef(oid) INTO src,ddl FROM pg_proc WHERE oid=to_regprocedure(e->>'sig');
 SELECT patched_body INTO saved FROM public.cage_staff_workflow_backup_20261008 WHERE signature=e->>'sig';
 IF FOUND THEN
  IF src IS DISTINCT FROM saved THEN RAISE EXCEPTION 'Function changed since patch: %',e->>'sig';END IF;
 ELSE
  IF src IS DISTINCT FROM e->>'old' THEN RAISE EXCEPTION 'Unexpected function version: %. No changes applied.',e->>'sig';END IF;
  INSERT INTO public.cage_staff_workflow_backup_20261008 VALUES(e->>'sig',ddl,e->>'new');
  EXECUTE replace(ddl,src,e->>'new');
 END IF;
END LOOP;
END $patch$;

CREATE OR REPLACE FUNCTION public.module_level(m text) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF m IN ('projects','requests','tasks','crm','commercial','finance','approvals') AND EXISTS(select 1 from profiles where id=auth.uid() and active and role<>'shared') THEN RETURN 'edit';END IF;
 RETURN collaboration_original_module_level(m);
END $$;
REVOKE ALL ON FUNCTION public.module_level(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.module_level(text) TO authenticated;
create or replace function public.staff_edit_finance_document(doc_type text, expected_record jsonb, edits jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare w workspace_states; k text; old_record jsonb; r jsonb; result jsonb; item jsonb;
 total numeric=0; paid numeric=0; is_revision boolean=false; new_number bigint; field text;
begin
 if not exists(select 1 from profiles where id=auth.uid() and active and role<>'shared') or module_level('finance')<>'edit' then
 raise exception 'Finance edit access is required. Contact your administrator.' using errcode='42501';end if;
 if doc_type is null or doc_type not in ('quote','invoice') then raise exception 'Invalid document type';end if;
 k=case when doc_type='quote' then 'quotes' else 'invoices' end;
 select * into w from workspace_states where organization_id=current_organization_id() for update;
 select x into old_record from jsonb_array_elements(coalesce(w.data->k,'[]')) x where x->>'id'=expected_record->>'id';
 if old_record is null or not record_visible(k,old_record,w.data) then raise exception 'This document is outside your access. Contact your administrator.' using errcode='42501';end if;
 if old_record is distinct from expected_record then raise exception 'This document changed since you opened it. Your form is still available; reopen the latest document before saving.';end if;
 if jsonb_typeof(edits) is distinct from 'object' then raise exception 'Invalid edits';end if;
 for field in select jsonb_object_keys(edits) loop
 if field not in ('client','recipient','description','issued','validUntil','due','items','currency','preparedBy','serviceDetails','paymentDetails','project','deal') then raise exception 'Cannot edit field: %',field;end if;
 end loop;
 r=old_record||edits;
 if coalesce(trim(r->>'client'),'')='' or coalesce(trim(r->>'recipient'),'')='' or coalesce(trim(r->>'description'),'')='' then raise exception 'Complete the client, recipient and description';end if;
 if coalesce(r->>'issued','')='' or coalesce(r->>(case when doc_type='quote' then 'validUntil' else 'due' end),'')='' then raise exception 'Complete the document dates';end if;
 if (r->>(case when doc_type='quote' then 'validUntil' else 'due' end))::date < (r->>'issued')::date then raise exception 'The expiry or due date cannot precede the issue date';end if;
 if coalesce(r->>'currency','') !~ '^[A-Z]{3}$' then raise exception 'Choose a valid currency';end if;
 if jsonb_typeof(r->'items') is distinct from 'array' then raise exception 'Add document line items';end if;
 for item in select x from jsonb_array_elements(r->'items') x loop
 if coalesce(trim(item->>'description'),'')='' or jsonb_typeof(item->'quantity') is distinct from 'number' or jsonb_typeof(item->'unitPrice') is distinct from 'number'
 then raise exception 'Complete each line item';end if;
 if (item->>'quantity')::numeric<=0 or (item->>'unitPrice')::numeric<0 then raise exception 'Invalid quantity or unit price';end if;
 total=total+round((item->>'quantity')::numeric*(item->>'unitPrice')::numeric,2);
 end loop;
 if total<=0 then raise exception 'Document total must be positive';end if;
 -- Preserve immutable snapshots and stop editing while a send may be in flight.
 if exists(select 1 from document_sends_v2 where organization_id=w.organization_id and document_type=doc_type and document_id=old_record->>'id' and created_at>now()-interval '2 minutes' and provider_id is null) then
 raise exception 'A recent delivery attempt is still unresolved. Wait two minutes and check Delivery history before editing.';end if;
 is_revision=doc_type='quote' and (old_record->>'status'='Accepted' or old_record->'clientResponse'->>'decision'='Accepted');
 r=r||jsonb_build_object('amount',total,'revision',coalesce((old_record->>'revision')::int,0)+1,'editedAt',now(),'editedBy',auth.uid(),'automaticFollowUp',false);
 if doc_type='invoice' then
 select coalesce(sum(amount),0) into paid from invoice_payments where organization_id=w.organization_id and invoice_id=old_record->>'id';
 if total<paid then raise exception 'Invoice total cannot be lower than recorded payments (%)',paid;end if;
 if (paid>0 or old_record->>'status'='Paid') and r->>'currency' is distinct from coalesce(old_record->>'currency','MWK') then raise exception 'Currency cannot change after payment';end if;
 if old_record->>'status'='Paid' and paid=0 and total is distinct from (old_record->>'amount')::numeric then raise exception 'Reconcile the payments for this older Paid invoice before changing its total';end if;
 r=r||jsonb_build_object('status',case when paid>=total or (old_record->>'status'='Paid' and paid=0) then 'Paid' when paid>0 then 'Sent' else 'Draft' end);
 else r=r||jsonb_build_object('status','Draft');end if;
 if is_revision then
 select greatest(26000,coalesce(max(substring(x->>'number' from '^Q-([0-9]+)$')::bigint),0))+1 into new_number from jsonb_array_elements(coalesce(w.data->'quotes','[]')) x;
 r=(r-array['clientResponse','staffAcceptance','sentAt','request','paid','paidAmount'])||jsonb_build_object('id','q-'||gen_random_uuid(),'number','Q-'||new_number,'createdBy',staff_member_id(auth.uid()),'revisionOf',old_record->>'id','revisionOfNumber',old_record->>'number');
 end if;
 insert into public.staff_document_edit_versions(organization_id,document_type,document_id,actor_id,old_record,new_record) values(w.organization_id,doc_type,r->>'id',auth.uid(),old_record,r);
 result=save_workspace_changes(jsonb_build_array(jsonb_build_object('key',k,'id',r->>'id','before',case when is_revision then null else old_record end,'after',r)),w.data->>'_resetEpoch');
 if coalesce((result->>'ok')::boolean,false) is not true then raise exception 'Document changed. Reopen the current version before saving.';end if;
 insert into audit_log(organization_id,actor_id,action,entity_type,entity_id,old_data,new_data)
 values(w.organization_id,auth.uid(),case when is_revision then 'document.revision_created' else 'document.edited' end,doc_type,r->>'id',old_record,r);
 return jsonb_build_object('record',r,'newRevision',is_revision);
end $$;
revoke all on function public.staff_edit_finance_document(text,jsonb,jsonb) from public,anon;
grant execute on function public.staff_edit_finance_document(text,jsonb,jsonb) to authenticated;

CREATE OR REPLACE FUNCTION public.staff_edit_work_record(kind text,expected_record jsonb,edits jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE w workspace_states;r jsonb;cur jsonb;field text;result jsonb;
BEGIN
 IF NOT EXISTS(select 1 from profiles where id=auth.uid() and active and role<>'shared') THEN RAISE EXCEPTION 'An active staff account is required' USING errcode='42501';END IF;
 IF kind IS NULL OR kind NOT IN ('projects','requests') OR module_level(kind)<>'edit' THEN RAISE EXCEPTION 'This section is outside your edit access' USING errcode='42501';END IF;
 SELECT * INTO w FROM workspace_states WHERE organization_id=current_organization_id() FOR UPDATE;
 SELECT x INTO cur FROM jsonb_array_elements(coalesce(w.data->kind,'[]')) x WHERE x->>'id'=expected_record->>'id';
 IF cur IS NULL OR NOT record_visible(kind,cur,w.data) THEN RAISE EXCEPTION 'Record unavailable' USING errcode='42501';END IF;
 IF cur IS DISTINCT FROM expected_record THEN RAISE EXCEPTION 'This record changed while you were editing. Reopen it to review the latest version; your form is still available.';END IF;
 IF jsonb_typeof(edits) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid edits';END IF;
 FOR field IN SELECT jsonb_object_keys(edits) LOOP
 IF (kind='projects' AND field NOT IN ('name','client','deadline','category','outcome')) OR (kind='requests' AND field NOT IN ('title','organisation','contact','contactDetail','deadline','summary','nextAction')) THEN RAISE EXCEPTION 'Invalid edit field: %',field;END IF;
 END LOOP;
 r=cur||edits;
 IF coalesce(trim(r->>CASE WHEN kind='projects' THEN 'name' ELSE 'title' END),'')='' THEN RAISE EXCEPTION 'Add a name';END IF;
 result=save_workspace_changes(jsonb_build_array(jsonb_build_object('key',kind,'id',r->>'id','before',cur,'after',r)),w.data->>'_resetEpoch');
 IF coalesce((result->>'ok')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'Record changed. Reopen the latest version.';END IF;
 INSERT INTO audit_log(organization_id,actor_id,action,entity_type,entity_id,old_data,new_data) VALUES(w.organization_id,auth.uid(),'record.edited',kind,r->>'id',cur,r);
 RETURN jsonb_build_object('record',r);
END $$;
REVOKE ALL ON FUNCTION public.staff_edit_work_record(text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_edit_work_record(text,jsonb,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
SELECT 'Staff workflow and editing installed' AS result;
